class Solution {
public:
    int maximumCostSubstring(std::string s, std::string chars, std::vector<int>& vals) {
        std::vector<int> cost(26);
        for (int i = 0; i < 26; ++i) cost[i] = i + 1;
        for (int i = 0; i < (int)chars.size(); ++i) cost[chars[i] - 'a'] = vals[i];
        int max_cost = 0, curr = 0;
        for (char ch : s) {
            curr = std::max(0, curr + cost[ch - 'a']);
            max_cost = std::max(max_cost, curr);
        }
        return max_cost;
    }
};

class Solution {
    public int maximumCostSubstring(String s, String chars, int[] vals) {
        int[] cost = new int[26];
        for (int i = 0; i < 26; i++) cost[i] = i + 1;
        for (int i = 0; i < chars.length(); i++) cost[chars.charAt(i) - 'a'] = vals[i];
        int maxCost = 0, curr = 0;
        for (char ch : s.toCharArray()) {
            curr = Math.max(0, curr + cost[ch - 'a']);
            maxCost = Math.max(maxCost, curr);
        }
        return maxCost;
    }
}

var maximumCostSubstring = function(s, chars, vals) {
    const cost = new Int32Array(26);
    for (let i = 0; i < 26; i++) cost[i] = i + 1;
    for (let i = 0; i < chars.length; i++) cost[chars.charCodeAt(i) - 97] = vals[i];
    let maxCost = 0, curr = 0;
    for (let i = 0; i < s.length; i++) {
        curr = Math.max(0, curr + cost[s.charCodeAt(i) - 97]);
        maxCost = Math.max(maxCost, curr);
    }
    return maxCost;
